/* Existing RedFox operations, simulated locally. Never calls production services. */
(() => {
  'use strict';
  const key='diandeng.prototype.redfox.v1';
  const platforms={dy:'抖音',xhs:'小红书',gzh:'公众号','ai-gzh':'AI 公众号','ai-bili':'AI B站','ai-xhs':'AI 小红书'};
  const items=Object.keys(platforms).flatMap((platform,i)=>Array.from({length:4},(_,n)=>({id:platform+'-'+n,platform,title:['AI 会议纪要怎样避免漏掉负责人','用 AI 做周报，先整理哪些材料','AI 简历修改怎样保留真实经历','AI 表格分析先核对原始数据'][n],author:'演示账号 '+(i+1),likes:240+n*71,comments:12+n*9,saves:110+n*32,views:3400+n*430,body:'演示作品摘要：先提出工作问题，再展示操作步骤，最后检查材料来源与适用边界。\n这是预置素材，不是实际博主的作品或互动数据。'})));
  const seed=()=>({schema:1,hot:'dy',removed:[],auto:{},history:[],query:'',searchPlatforms:['dy','xhs','gzh'],searchSize:4,cache:null,results:[],saved:[],accounts:[],group:'全部',logs:[],jobs:{},configured:true,quota:20});
  let s=seed(),ui={error:'',searched:false,detail:null,back:'original',input:'',tool:'检测',result:'',busy:false,cache:false},h;
  try{const v=JSON.parse(localStorage.getItem(key));if(v){const valid=v.schema===1&&['removed','history','results','saved','accounts','logs'].every(k=>Array.isArray(v[k]))&&v.auto&&v.jobs&&Number.isFinite(v.quota)&&v.removed.every(k=>platforms[k])&&v.history.every(x=>typeof x==='string')&&v.results.every(id=>items.some(x=>x.id===id))&&v.saved.every(id=>items.some(x=>x.id===id))&&v.accounts.every(a=>a&&['id','name','account','group'].every(k=>typeof a[k]==='string')&&platforms[a.platform])&&v.logs.every(l=>l&&['at','action','dependency'].every(k=>typeof l[k]==='string'))&&typeof v.query==='string'&&(!v.searchPlatforms||Array.isArray(v.searchPlatforms)&&v.searchPlatforms.every(p=>['dy','xhs','gzh'].includes(p)))&&(!v.cache||typeof v.cache.key==='string'&&Number.isFinite(v.cache.at)&&Array.isArray(v.cache.results)&&v.cache.results.every(id=>items.some(x=>x.id===id)));if(!valid)throw Error();s={...seed(),...v};ui.searched=!!s.cache;ui.detail=s.detail||null;ui.back=s.detailBack||'original';}}catch{ui.error='演示数据无法读取，原存档未覆盖。';}
  function save(){try{if(ui.error==='演示数据无法读取，原存档未覆盖。'){localStorage.setItem(key+'.backup-'+Date.now(),localStorage.getItem(key)||'');ui.error='';}localStorage.setItem(key,JSON.stringify(s));return true;}catch{h.notify('RedFox 演示保存失败；当前页面保留，刷新可能丢失。');return false;}}
  const time=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date());
  const log=(action,dependency='RedFox')=>{s.logs.unshift({at:time(),action,dependency});s.logs=s.logs.slice(0,50);save();};
  const b=(text,action,id='',primary=false)=>h.button(h.unified&&action==='topic'?'用于创作':h.unified&&action==='creator-topic'?'加入文稿':text,'rf-'+action,primary,`data-rf-id="${h.esc(id)}"`);
  const fields=(name,label,value='',type='text')=>`<label class="pui-field"><span class="pui-label">${label}</span><input class="pui-control" name="${name}" type="${type}" value="${h.esc(value)}" required maxlength="120"></label>`;
  const links={original:'全网热榜','rf-search':'跨平台搜索','rf-tracker':'账号追踪','rf-creator':'原创作工具','rf-library':'素材收藏','rf-settings':'运行设置'};
  function shell(route,title,desc,body,actions=''){
    const scoped=h.unified?(['original','rf-search','rf-tracker','rf-detail'].includes(route)?{original:'全网热榜','rf-search':'跨平台搜索','rf-tracker':'账号追踪'}:route==='rf-library'?{knowledge:'知识库','rf-library':'RedFox 收藏'}:route==='rf-creator'?{editor:'当前内容','rf-creator':'原工具兼容'}:{settings:'设置','rf-settings':'运行设置'}):links;
    const heading=h.unified&&location.hash==='#sources'?`<h2 class="unified-subhead">${title}</h2><p class="unified-meta">${desc}</p>`:h.head(title,desc,actions);
    return heading+`<nav class="rf-tabs" aria-label="RedFox 功能">${Object.entries(scoped).map(([k,v])=>`<a href="#${k}" ${route===k?'aria-current="page"':''}>${v}</a>`).join('')}</nav><p class="rf-boundary">原功能交互演示 · 数据全部预置 · 不调用接口、不消耗点数</p>${ui.error?`<p role="alert" class="pui-error">${h.esc(ui.error)}</p>`:''}${body}`;
  }
  const find=id=>items.find(x=>x.id===id);
  function rows(list){return list.length?list.map((x,n)=>`<article class="rf-work-row"><span class="rf-rank">${String(n+1).padStart(2,'0')}</span><div class="source-text"><span class="pui-tag">${platforms[x.platform]}</span><h2>${h.esc(x.title)}</h2><p class="source-meta">${h.esc(x.author)} · 演示数据</p><div class="rf-metrics"><span>${x.platform==='gzh'?'阅读':'点赞'} ${x.platform==='gzh'?x.views:x.likes}</span><span>评论 ${x.comments}</span><span>收藏 ${x.saves}</span></div></div><div class="rf-row-actions">${b('查看详情','detail',x.id)}${b(s.saved.includes(x.id)?'已收藏':'收藏素材','save',x.id)}${h.unified?b('收藏 OB','collect-ob',x.id):''}${b('转为选题','topic',x.id)}</div></article>`).join(''):'<div class="rf-empty"><h3>暂无作品</h3><p>调整平台或关键词，或刷新演示数据。</p></div>';}
  function hot(){const tabs=Object.entries(platforms).filter(([k])=>!s.removed.includes(k));if(!tabs.some(([k])=>k===s.hot))s.hot=tabs[0]?.[0]||'';
    return shell('original','RedFox 全网热榜','保留热点浏览、平台榜单、自动刷新与趋势分析。',
      h.panel('全网关键词',`<div class="rf-keywords">${['AI 会议纪要','AI 周报','AI 简历','表格分析'].map(k=>b(k,'keyword',k)).join('')}</div><div class="inline-actions">${b('刷新热点','refresh','keywords')}${b('趋势分析','trends')}</div><p class="pui-help">示例缓存 · 采集时间 2026-10-12 09:00 · 非实时热点</p>`)+
      h.panel('平台热榜',`<div class="source-filter">${tabs.map(([k,v])=>h.button(v,'rf-hot',false,`data-rf-id="${k}" aria-pressed="${s.hot===k}"`)).join('')}</div>${s.hot?`<div class="rf-toolbar"><span class="source-meta">${platforms[s.hot]} · 本地示例缓存 · 4 条作品</span><div class="inline-actions">${b('刷新榜单','refresh',s.hot)}${b(s.auto[s.hot]===false?'开启刷新':'暂停刷新','auto',s.hot)}${b('移除榜单','remove-tab',s.hot)}</div></div>${rows(items.filter(x=>x.platform===s.hot))}`:'<p>暂无榜单；恢复后可继续浏览。</p>'}${s.removed.length?b('恢复榜单','restore-tabs'):''}`));
  }
  function search(){return shell('rf-search','跨平台搜索','一次选择多个平台，保留搜索历史、缓存提示和作品详情。',
    h.panel('搜索条件',`<form id="rf-search-form"><label class="pui-field"><span class="pui-label">搜索关键词</span><input class="pui-control" name="query" maxlength="120" value="${h.esc(s.query)}" placeholder="例如：AI 周报"></label><div class="pui-check-row">${['dy','xhs','gzh'].map(k=>`<label class="pui-checkbox"><input name="platform" type="checkbox" value="${k}" ${s.searchPlatforms.includes(k)?'checked':''}>${platforms[k]}</label>`).join('')}</div><label class="pui-field"><span class="pui-label">每平台条数</span><select class="pui-control" name="size">${[2,4].map(n=>`<option value="${n}" ${s.searchSize===n?'selected':''}>${n} 条（演示）</option>`).join('')}</select></label><div class="inline-actions"><button class="pui-btn pui-btn-primary" type="submit">查询</button>${b('重置条件','reset-search')}${b('重新搜索','retry-search')}</div><p class="pui-error" id="rf-search-error" role="alert"></p></form><div class="rf-history"><span class="source-meta">搜索历史</span>${s.history.map(x=>b(h.esc(x),'keyword',x)).join('')}${s.history.length?b('清空历史','clear-history'):''}</div>`)+
    h.panel('搜索结果',`<p role="status" class="source-meta">${ui.searched?(ui.cache?'使用演示缓存；重新搜索可绕过缓存。':'演示查询完成；'+s.results.length+' 条结果。'):'尚未查询；预置演示素材不是联网搜索结果。'}</p>${rows(s.results.map(find).filter(Boolean))}`));}
  function detail(){const x=find(ui.detail);if(!x)return shell('rf-detail','作品详情','作品未找到。',b('返回热榜','back'));
    return shell('rf-detail','作品详情','查看内容与互动信息，再决定收藏或创作。',
      `<div class="inline-actions">${b('返回列表','back')}${b('刷新详情','refresh',x.id)}</div>`+h.panel(x.title,`<p>${platforms[x.platform]} · ${h.esc(x.author)} · 演示作品</p><div class="rf-metrics rf-metrics-large">${(x.platform==='gzh'?[['阅读',x.views],['在看',x.likes],['评论',x.comments]]:x.platform==='dy'?[['点赞',x.likes],['评论',x.comments],['分享',90],['收藏',x.saves],['播放',x.views]]:[['点赞',x.likes],['收藏',x.saves],['评论',x.comments],['分享',90]]).map(([label,value])=>`<span>${label}<b>${value}</b></span>`).join('')}</div><p class="rf-copy">${h.esc(x.body)}</p>${x.platform==='gzh'?'<p class="pui-help">公众号可能仅返回摘要，缺少正文时应打开原文。</p>':''}<div class="inline-actions">${b(s.saved.includes(x.id)?'已收藏':'收藏素材','save',x.id)}${b('追踪作者','track',x.id)}${b('原AI创作','to-creator',x.id)}${b('转为选题','topic',x.id,true)}${b('打开原文','origin',x.id)}${h.unified?b('收藏 OB','collect-ob',x.id):''}</div>`)+
      h.panel('评论信息',`<p>保留评论数量：${x.comments}（模拟）。</p><p class="pui-help">现有 RedFox 页面未找到评论全文接口。</p>${b('查看边界','comments')}`));}
  function tracker(){const list=s.accounts.filter(a=>s.group==='全部'||a.group===s.group);return shell('rf-tracker','账号追踪','保留分组、账号编辑、作品同步、评分诊断与趋势记录。',
    `<div class="source-filter">${['全部','自己','竞品','灵感来源','同赛道'].map(g=>h.button(g,'rf-group',false,`data-rf-id="${g}" aria-pressed="${s.group===g}"`)).join('')}</div>`+h.panel('追踪账号',list.length?list.map(a=>`<article class="rf-account"><div><span class="pui-tag">${platforms[a.platform]}</span><h2>${h.esc(a.name)}</h2><p class="source-meta">${h.esc(a.account)} · ${a.group} · ${a.synced?'示例作品已同步':'尚未同步'}</p></div><div class="inline-actions">${b('查看作品','account-works',a.id)}${b('同步作品','sync-account',a.id)}${b('评分详情','diagnose',a.id)}${b('账号趋势','account-trend',a.id)}${b('编辑账号','edit-account',a.id)}${b('移除账号','remove-account',a.id)}${b('上移账号','move-account',a.id)}</div></article>`).join(''):'<div class="rf-empty"><h3>暂无追踪账号</h3><p>从作品详情追踪作者，或手动添加。</p></div>'),b('添加账号','add-account','',true));}
  function accountForm(a){h.modal(a?'编辑账号':'添加账号',`<form id="rf-account-form" data-id="${a?.id||''}"><div class="pui-form-columns">${fields('name','账号名称',a?.name)}${fields('account','平台账号',a?.account)}<label class="pui-field"><span class="pui-label">所属平台</span><select name="platform" class="pui-control">${['dy','xhs','gzh'].map(k=>`<option value="${k}" ${a?.platform===k?'selected':''}>${platforms[k]}</option>`).join('')}</select></label><label class="pui-field"><span class="pui-label">账号分组</span><select name="group" class="pui-control">${['自己','竞品','灵感来源','同赛道'].map(k=>`<option ${a?.group===k?'selected':''}>${k}</option>`).join('')}</select></label></div><p class="pui-help">仅保存演示资料，不验证真实账号。</p><p class="pui-error" id="rf-account-error" role="alert"></p><button class="pui-btn pui-btn-primary" type="submit">保存账号</button></form>`);}
  function creator(){return shell('rf-creator','原创作工具','保留原检测、改写、风格、热点关联与 RedFox 封面入口。',
    `<div class="source-filter">${['创作','改写','检测','热点关联','封面'].map(v=>h.button(v,'rf-tool',false,`data-rf-id="${v}" aria-pressed="${ui.tool===v}"`)).join('')}</div>`+
    h.panel('输入材料',`<form id="rf-tool-form"><label class="pui-field"><span class="pui-label">${ui.tool==='创作'?'主题大纲':'原始内容'}</span><textarea name="content" class="pui-control" rows="7" maxlength="60000" placeholder="${ui.tool==='创作'?'输入主题、大纲和已核验材料':'输入或从作品详情带入内容'}">${h.esc(ui.input)}</textarea></label><div class="pui-form-columns"><label class="pui-field"><span class="pui-label">创作平台</span><select class="pui-control" name="platform">${['公众号','小红书','抖音'].map(v=>`<option>${v}</option>`).join('')}</select></label><label class="pui-field"><span class="pui-label">表达风格</span><select class="pui-control" name="style"><option>个人表达</option><option>步骤教程</option><option>工具实测</option></select></label></div><p class="pui-help">${ui.tool==='检测'?'违禁词检测依赖 RedFox。':ui.tool==='封面'?'原封面依赖 RedFox；新主线的 Codex 配图独立保留。':'创作、改写与深度分析依赖模型；本原型不运行模型。'}</p><p id="rf-tool-error" class="pui-error" role="alert"></p><div class="inline-actions"><button class="pui-btn pui-btn-primary" type="submit">${{创作:'模拟创作',检测:'模拟检测',改写:'模拟改写',热点关联:'关联热点',封面:'封面任务'}[ui.tool]}</button>${b('调用日志','logs')}</div></form>`)+
    h.panel('任务结果',ui.result?`<div class="rf-copy" role="status">${h.esc(ui.result)}</div><div class="inline-actions">${b('带入选题','creator-topic')}${b('导出结果','export-result')}</div>`:'<p class="muted">等待输入；不显示虚假的真实检测结论。</p>'));}
  function library(){return shell('rf-library','素材收藏','收藏与选题分开管理，原知识库的导出入口保留。',h.panel('已收藏素材',rows(s.saved.map(find).filter(Boolean))+`${s.saved.length?'<div class="inline-actions">'+b('导出素材','export-saved')+b('清空收藏','clear-saved')+'</div>':''}`)+h.panel('知识库衔接','<p>原知识库、Notion、RSS 与 OB 入口保留；这轮不改变正式同步权限。</p><p class="pui-help">新主线先只读选定 OB 笔记，成品另行确认归档。</p><div class="inline-actions"><a class="pui-btn" href="#topics">进入选题库</a>'+h.button('选 OB 素材','ob-preview')+'</div>'));}
  function settings(){return shell('rf-settings','运行设置','凭证、额度、任务、通知、缓存与日志分开核对。',
    h.panel('能力与额度',`<div class="rf-toolbar"><p>RedFox：${s.configured?'已配置（模拟）':'未配置（模拟）'}<br>模型与 Codex：原型不连接<br>点数预算：${s.quota}（演示值）</p><div class="inline-actions">${b('切换配置','configured')}${b('修改预算','budget')}${b('调用日志','logs')}${b('诊断系统','health')}</div></div><p class="pui-help">禁止在原型输入真实密钥；生产凭证保持不变。</p>`)+
    h.panel('自动任务',`<div class="rf-job-list">${['热点实时采集','热点趋势分析','热点日报','账号每日同步','缓存清理','用量清理','RSS 同步'].map(k=>`<div class="rf-toolbar"><span>${k}</span>${b(s.jobs[k]===false?'已暂停':'已开启','job',k)}</div>`).join('')}</div>`)+
    h.panel('通知与数据','<div class="inline-actions">'+b('通知配置','notifications')+b('查看缓存','cache')+b('清理缓存','clear-cache')+b('备份演示','backup')+'</div><p class="pui-help">原任务计划、通知地址和生产缓存不受影响。</p>'));}
  function confirm(title,text,action,id=''){h.modal(title,`<p>${text}</p><p class="pui-help">仅影响演示数据，正式功能不变。</p><div class="inline-actions">${b('确认操作',action,id,true)}${h.button('取消','close')}</div>`);}
  function task(action,dependency,run){if(ui.busy)return h.notify('已有演示任务，请等待。');if(dependency==='RedFox'&&!s.configured){h.notify('请在运行设置启用演示配置。');return;}h.modal('确认模拟调用',`<p>${action} · ${dependency}</p><p>正式操作可能消耗额度；原型不请求接口。</p><div class="inline-actions">${b('开始模拟','run-task',action,true)}${h.button('取消','close')}</div>`);ui.pending={action,dependency,run};}
  function handle(a,id){
    if(a==='hot'){s.hot=id;save();return h.render();}
    if(a==='detail'){ui.back=location.hash.slice(1);ui.detail=id;s.detail=id;s.detailBack=ui.back;save();return h.route('rf-detail');}
    if(a==='back')return h.route(ui.back);
    if(a==='keyword'){s.query=id;save();h.route('rf-search');requestAnimationFrame(()=>document.querySelector('#rf-search-form')?.requestSubmit());return;}
    if(a==='save'){if(!s.saved.includes(id)){s.saved.unshift(id);save();}h.notify('已收藏演示素材。');return h.render();}
    if(a==='topic'){const x=find(id);return h.newTopic({id:'rf:'+id,group:'RedFox',title:x.title,text:x.body});}
    if(a==='collect-ob'){const x=find(id);return h.collectKnowledge?.({id:'rf:'+id,group:'RedFox',title:x.title,text:x.body});}
    if(a==='origin')return h.modal('打开原作品','<p>演示作品没有真实原文地址。</p><p>正式页应打开接口返回的原链接，不拼造链接。</p>'+h.button('返回详情','close'));
    if(a==='comments')return h.modal('评论能力边界','<p>原详情保留评论数量。当前代码没有 RedFox 评论全文入口。</p><p>小红书 MCP 评论能力是独立依赖，不能标成 RedFox 已接通。</p>'+h.button('返回详情','close'));
    if(a==='refresh')return task('刷新 '+(platforms[id]||'详情与热点'),'RedFox',()=>{ui.error='';h.notify('模拟刷新完成；仍为预置数据。');});
    if(a==='trends')return task('深度分析趋势','模型',()=>h.modal('趋势分析（模拟）','<p>示例观察：工作场景需要把“AI 能做什么”转成“如何核对结果”。</p><p>正式分析需显示真实时间、来源与模型结果。</p>'+h.button('关闭','close')));
    if(a==='auto'){s.auto[id]=s.auto[id]===false;save();return h.render();}
    if(a==='remove-tab')return confirm('移除平台榜单','同时移除演示自动选题的对应信源；不会删除历史收藏。','confirm-remove-tab',id);
    if(a==='confirm-remove-tab'){s.removed.push(id);save();h.close();return h.render();}
    if(a==='restore-tabs'){s.removed=[];save();return h.render();}
    if(a==='reset-search'){s.query='';s.results=[];s.cache=null;s.searchPlatforms=['dy','xhs','gzh'];s.searchSize=4;ui.searched=false;save();return h.render();}
    if(a==='retry-search'){const form=document.querySelector('#rf-search-form');ui.cache=false;form.dataset.fresh='true';return form.requestSubmit();}
    if(a==='clear-history')return confirm('清空搜索历史','只清空演示搜索历史，收藏素材保留。','confirm-clear-history');
    if(a==='confirm-clear-history'){s.history=[];save();h.close();return h.render();}
    if(a==='track'){const x=find(id);if(s.accounts.some(v=>v.account===x.author&&v.platform===x.platform))return h.notify('作者已在追踪列表。');s.accounts.unshift({id:crypto.randomUUID(),name:x.author,account:x.author,platform:x.platform,group:'灵感来源',synced:false});s.group='全部';save();return h.route('rf-tracker');}
    if(a==='group'){s.group=id;save();return h.render();}
    if(a==='add-account'||a==='edit-account')return accountForm(s.accounts.find(v=>v.id===id));
    if(a==='remove-account')return confirm('移除追踪账号','保留已收藏素材，只移除演示追踪关系。','confirm-remove-account',id);
    if(a==='confirm-remove-account'){s.accounts=s.accounts.filter(v=>v.id!==id);save();h.close();return h.render();}
    if(a==='move-account'){const i=s.accounts.findIndex(v=>v.id===id);if(i>0)[s.accounts[i-1],s.accounts[i]]=[s.accounts[i],s.accounts[i-1]];save();return h.render();}
    if(a==='sync-account')return task('同步账号作品','RedFox',()=>{const account=s.accounts.find(v=>v.id===id);if(account)account.synced=true;save();h.render();h.notify('示例作品已同步。');});
    if(a==='account-works'){const v=s.accounts.find(v=>v.id===id);return h.modal('账号作品',v.synced?rows(items.filter(x=>x.platform===v.platform)):'<p>暂无本地示例作品，请先同步。</p>'+b('同步作品','sync-account',id));}
    if(a==='diagnose'||a==='account-trend')return task(a==='diagnose'?'评分诊断':'账号趋势','RedFox',()=>h.modal(a==='diagnose'?'评分详情（模拟）':'账号趋势（模拟）','<p>尚无真实数据，不能据此判断账号表现。</p><p>正式页保留评分说明、时间范围、数据缺口与重新诊断。</p>'+b('重新诊断',a,id)));
    if(a==='to-creator'){ui.input=find(id).body;ui.result='';return h.route('rf-creator');}
    if(a==='tool'){ui.input=document.querySelector('#rf-tool-form [name=content]')?.value||ui.input;ui.tool=id;ui.result='';return h.render();}
    if(a==='creator-topic')return h.newTopic({id:'rf-creator:'+ui.input.slice(0,80),group:'RedFox',title:'原工具创作结果',text:ui.result||ui.input});
    if(a==='export-result'||a==='export-saved'||a==='backup')return h.download(a==='export-result'?ui.result:a==='export-saved'?JSON.stringify(s.saved.map(find),null,2):JSON.stringify(s,null,2),'RedFox-演示导出.json','application/json');
    if(a==='clear-saved')return confirm('清空素材收藏','只删除演示收藏记录，不删除选题。','confirm-clear-saved');
    if(a==='confirm-clear-saved'){s.saved=[];save();h.close();return h.render();}
    if(a==='configured'){s.configured=!s.configured;save();return h.render();}
    if(a==='budget')return h.modal('修改演示预算',`<form id="rf-budget-form">${fields('quota','点数预算',s.quota,'number')}<p class="pui-help">范围 1 ~ 1000；不是实际 RedFox 余额。</p><p class="pui-error" id="rf-budget-error" role="alert"></p><button class="pui-btn pui-btn-primary" type="submit">保存预算</button></form>`);
    if(a==='job'){s.jobs[id]=s.jobs[id]===false;save();return h.render();}
    if(a==='logs')return h.modal('调用审计（模拟）',s.logs.length?s.logs.map(v=>`<div class="rf-log"><span>${v.at}</span><strong>${h.esc(v.action)}</strong><span>${v.dependency} · 模拟成功</span></div>`).join(''):'<p>尚无模拟调用记录。</p>');
    if(a==='health')return h.modal('能力诊断（模拟）',`<p>RedFox 配置：${s.configured?'已配置':'未配置'}（模拟）。</p><p>信源、模型、Codex 与发布接口均未连接。</p><p>请在正式系统中分别验证，原型可点击不代表接口可用。</p>`);
    if(a==='notifications')return h.modal('通知配置（模拟）','<p>原配置支持 Discord、Bark、Webhook、钉钉、飞书、Telegram。</p><label class="pui-field"><span class="pui-label">通知渠道</span><select class="pui-control"><option>飞书</option><option>钉钉</option><option>Telegram</option><option>Discord</option><option>Bark</option><option>Webhook</option></select></label><p class="pui-help">原型不保存真实通知地址、不发送消息。</p>'+b('测试通知','notification-test'));
    if(a==='notification-test')return h.notify('通知演示完成，没有发送真实消息。');
    if(a==='cache')return h.modal('缓存状态（模拟）',`<p>搜索缓存 ${s.results.length} 条 · 历史 ${s.history.length} 条</p><p>正式搜索缓存 30 分钟；原型未复制真实缓存。</p>`+b('清理缓存','clear-cache'));
    if(a==='clear-cache')return confirm('清理搜索缓存','只清理演示搜索结果，历史、收藏、账号和作品保留。','confirm-clear-cache');
    if(a==='confirm-clear-cache'){s.results=[];s.cache=null;ui.searched=false;save();h.close();return h.render();}
    if(a==='run-task'){const pending=ui.pending;if(!pending)return;ui.pending=null;ui.busy=true;h.close();h.notify('正在模拟 '+pending.action);setTimeout(()=>{ui.busy=false;log(pending.action,pending.dependency);pending.run();},350);}
  }
  function submit(f){const v=new FormData(f);
    if(f.id==='rf-search-form'){const q=String(v.get('query')).trim(),ps=v.getAll('platform'),size=Number(v.get('size'));if(!q||!ps.length){document.querySelector('#rf-search-error').textContent=!q?'请输入搜索关键词。':'至少选择一个平台。';return;}const cacheKey=JSON.stringify([q,[...ps].sort(),size]);ui.cache=f.dataset.fresh!=='true'&&s.cache?.key===cacheKey&&Date.now()-s.cache.at<30*60*1000;s.query=q;s.searchPlatforms=ps;s.searchSize=size;if(ui.cache)s.results=[...s.cache.results];else{s.results=items.filter(x=>ps.includes(x.platform)&&q.split(/\s+/).every(word=>x.title.includes(word))).filter((x,i,all)=>all.filter(y=>y.platform===x.platform).indexOf(x)<size).map(x=>x.id);s.cache={key:cacheKey,at:Date.now(),results:[...s.results]};}s.history=[q,...s.history.filter(x=>x!==q)].slice(0,50);ui.searched=true;save();h.render();}
    if(f.id==='rf-account-form'){const name=String(v.get('name')).trim(),account=String(v.get('account')).trim(),platform=v.get('platform');if(!name||!account){document.querySelector('#rf-account-error').textContent='请填写账号名称与平台账号。';return;}if(s.accounts.some(a=>a.id!==f.dataset.id&&a.account===account&&a.platform===platform)){document.querySelector('#rf-account-error').textContent='该账号已在追踪列表。';return;}const old=s.accounts.find(a=>a.id===f.dataset.id),next={id:old?.id||crypto.randomUUID(),name,account,platform,group:v.get('group'),synced:old?.account===account&&old?.platform===platform?old.synced:false};if(old)Object.assign(old,next);else s.accounts.unshift(next);s.group='全部';save();h.close();h.render();}
    if(f.id==='rf-budget-form'){const n=Number(v.get('quota'));if(!Number.isInteger(n)||n<1||n>1000){document.querySelector('#rf-budget-error').textContent='输入 1 ~ 1000 的整数。';return;}s.quota=n;save();h.close();h.render();}
    if(f.id==='rf-tool-form'){const text=String(v.get('content')).trim();if(!text){document.querySelector('#rf-tool-error').textContent='请先输入内容。';return;}ui.input=text;const tool=ui.tool;task('原工具'+tool,['检测','封面'].includes(tool)?'RedFox':'模型',()=>{ui.result=tool==='检测'?'模拟检测完成；这不是平台合规判定，正式功能展示真实命中词与位置。':tool==='封面'?'模拟封面任务完成；尚未生成图片。正式功能展示任务进度、失败原因与原图。':tool==='热点关联'?'热点关联（模拟）：AI 周报与信息核对。正式功能优先本地热点，无数据时确认联网。':'候选稿（模拟）：\n'+text+'\n\n请按本人实测修改，不把示例写成亲测结论。';h.render();});}
  }
  window.DiandengRedfox={labels:{...links,original:'RedFox 原工具','rf-detail':'作品详情'},init(helpers){h=helpers;document.addEventListener('click',e=>{const el=e.target.closest('[data-action^="rf-"]');if(el&&!el.disabled)handle(el.dataset.action.slice(3),el.dataset.rfId);});document.addEventListener('submit',e=>{if(['rf-search-form','rf-account-form','rf-tool-form','rf-budget-form'].includes(e.target.id)){e.preventDefault();submit(e.target);}});},render(route){return ({original:hot,'rf-search':search,'rf-detail':detail,'rf-tracker':tracker,'rf-creator':creator,'rf-library':library,'rf-settings':settings})[route]?.();}};
})();
